import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
const base = "06996d65dff05e53c7b18fae93a017d55c8c2d55";
const file = "scripts/audit-regressions.test.ts";
const found = spawnSync("git", ["show", base + ":" + file]);
if (found.status !== 0) { console.error("git show pinned base failed: " + found.status); process.exit(found.status ?? 2); }
let expected = found.stdout.toString("utf8");
function once(text, token, label) { const a=text.indexOf(token); if(a<0 || text.indexOf(token,a+token.length)>=0) throw new Error(label + ": expected exactly one marker"); return a; }
function replaceOnce(text, before, after, label) { const at=once(text,before,label); return text.slice(0,at)+after+text.slice(at+before.length); }
expected = replaceOnce(expected, 'import { artifactIsStale } from "./test-metrics";\n', "", "legacy import");
const coverageStart = "// ---------------------------------------------------------------------------\n// C-TEST-TIME-BUDGET-2-3EC1F016 T-008: coverage never falls.";
const coverageEnd = 'describe("C-CI-LINT-AND-PLAN-SHAPE-1-3526D6F0 CI governance lint", () => {';
const ca=once(expected,coverageStart,"coverage start"), cb=once(expected,coverageEnd,"coverage end");
if(cb<=ca) throw new Error("coverage markers out of order");
expected=expected.slice(0,ca)+expected.slice(cb);
const depthStart = "/** The fetch-depth declared on the `validate` job's own Checkout step, or null when absent. */";
const depthEnd = "/** The Windows job's own `run:` invocation that selects the grace-generate pin tests. */";
const da=once(expected,depthStart,"depth start"), db=once(expected,depthEnd,"depth end");
if(db<=da) throw new Error("depth markers out of order");
const oldBlock=expected.slice(da,db);
const itTitle='  it("README documents the fail-closed candidate refusal", () => {';
const ia=once(oldBlock,itTitle,"retained README test"), ie=oldBlock.indexOf("  });\n",ia)+"  });\n".length;
if(ie<=ia) throw new Error("retained README test end not found");
const retainedIt=oldBlock.slice(ia,ie);
const replacement='describe("C-LINUX-VALIDATION-REPAIR-1-DE5A1A05 README guard", () => {\n'+retainedIt+'});\n\n';
expected=expected.slice(0,da)+replacement+expected.slice(db);
expected=replaceOnce(expected,'it("prepin fixture discovery: planting a test file under the fixture makes metrics stale", () => {','it("prepin fixture discovery finds no test files", () => {',"fixture title");
const fixtureAt=expected.indexOf('describe("prepin fixture discovery", () => {');
const ma=expected.indexOf('    const metrics = path.join(repoRoot, "test-metrics.json");',fixtureAt), mb=expected.indexOf("  });\n});",ma);
if(fixtureAt<0 || ma<0 || mb<ma) throw new Error("metrics assertions region not found");
expected=expected.slice(0,ma)+expected.slice(mb);
const actual=readFileSync(file);
if(Buffer.compare(actual,Buffer.from(expected,"utf8"))!==0){console.error("audit file differs from exact approved transformation");process.exitCode=1;}
else console.log("audit exact-byte check OK");
BUN

AcceptanceCriteria.Criterion:
`scripts/test-metrics.test.ts` drives the real outer entry through the absolute Bun
executable (`process.execPath`) in a disposable project with a fake `bun` findable only
through `PATH` that records a sentinel per invocation, and captures stdout, stderr, the
direct exit, the report bytes, and the file bytes independently:
(a) a valid outside override under a missing parent directory succeeds and writes
exactly there; default output is a unique path outside the repository;
(b) an inside-repo override, and an override whose parent is a symlink resolving inside,
are refused before any write with zero fake-child invocations and the planted repository
file left byte-identical;
(c) a poisoned legacy `test-metrics.json` at the disposable root is unchanged and does
not influence the run, and the source no longer reads or writes it;
(d) child success with a missing, unreadable, and malformed report each exits nonzero
with no ranking;
(e) a launch failure and an unavailable child status each exit nonzero with exactly one
attempt and no retry;
(f) a fake child exiting 7 with a missing or malformed report leaves the outer exit at 7
and retains produced report bytes when present;
(g) a valid accepted run makes exactly one suite attempt, and the parser and ranking are
also driven directly (a planted slow case ranks first; a hostname in the JUnit is not
retained).

