bun - <<'BUN'
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
const base="06996d65dff05e53c7b18fae93a017d55c8c2d55", file=".github/workflows/validate.yml";
const old=spawnSync("git",["show",base+":"+file]);
if(old.status!==0){console.error("git show pinned workflow failed: "+old.status);process.exit(old.status??2);}
const baseline=Bun.YAML.parse(old.stdout.toString("utf8")), actual=Bun.YAML.parse(readFileSync(file,"utf8").toString());
const errors=[], j=actual?.jobs?.validate, steps=Array.isArray(j?.steps)?j.steps:[];
if(!j||typeof j!=="object") errors.push("jobs.validate missing or not an object");
const checkouts=steps.filter(s=>s?.name==="Checkout");
if(checkouts.length!==1||checkouts[0]?.uses!=="actions/checkout@v5"||Object.hasOwn(checkouts[0]??{},"with")) errors.push("validate Checkout must be actions/checkout@v5 with no inputs");
if(JSON.stringify(j?.env)!==JSON.stringify({NGRACE_TEST_REPORT_PATH:"${{ runner.temp }}/ngrace-test-reports/junit.xml"})) errors.push("validate job env must contain exactly the report path");
const ci=steps.filter(s=>s?.name==="Run CI validation"&&s?.run==="bun run validate:ci");
if(ci.length!==1) errors.push("exactly one Run CI validation step must run bun run validate:ci");
const uploads=steps.filter(s=>typeof s?.uses==="string"&&s.uses.startsWith("actions/upload-artifact@"));
if(uploads.length!==1||uploads[0]?.uses!=="actions/upload-artifact@v7") errors.push("validate must have exactly one actions/upload-artifact@v7 step");
const u=uploads[0], allowedStep=new Set(["name","uses","if","with"]), allowedWith=new Set(["name","path","if-no-files-found"]);
if(u&&Object.keys(u).some(k=>!allowedStep.has(k))) errors.push("upload step has unexpected step-level fields");
if(u&&Object.hasOwn(u,"name")&&(typeof u.name!=="string"||u.name.length===0)) errors.push("upload step name must be nonempty text");
if(u?.if!=="always()") errors.push("upload step must have if: always()");
if(u?.with?.path!=="${{ runner.temp }}/ngrace-test-reports/junit.xml") errors.push("upload path must be exactly the current JUnit report");
if(u?.with?.["if-no-files-found"]!=="ignore") errors.push("if-no-files-found must be ignore");
if(u?.with&&Object.keys(u.with).some(k=>!allowedWith.has(k))) errors.push("upload step has unexpected upload inputs");
if(Object.hasOwn(j??{},"continue-on-error")||steps.some(s=>Object.hasOwn(s??{},"continue-on-error"))) errors.push("continue-on-error is forbidden on validate job/steps");
if(ci.length===1&&uploads.length===1&&steps.indexOf(u)<=steps.indexOf(ci[0])) errors.push("upload step must follow the CI step");
if(!errors.length){
  const expected=structuredClone(baseline), ej=expected.jobs.validate;
  const checkout=ej.steps.find(s=>s.name==="Checkout");
  if(!checkout||checkout.uses!=="actions/checkout@v5"||!Object.hasOwn(checkout,"with")){console.error("pinned base checkout shape changed");process.exit(2);}
  delete checkout.with;
  ej.env={NGRACE_TEST_REPORT_PATH:"${{ runner.temp }}/ngrace-test-reports/junit.xml"};
  const ciIndex=ej.steps.findIndex(s=>s.name==="Run CI validation"&&s.run==="bun run validate:ci");
  if(ciIndex<0){console.error("pinned base CI step missing");process.exit(2);}
  ej.steps.splice(ciIndex+1,0,structuredClone(u));
  try{assert.deepStrictEqual(actual,expected);}catch{errors.push("workflow structure differs from pinned base beyond approved validate edits");}
}
if(errors.length){console.error(errors.join("\n"));process.exitCode=1;}
else console.log("workflow exact-structure check OK");
BUN

bun - <<'BUN'
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
const base="06996d65dff05e53c7b18fae93a017d55c8c2d55", file="README.md";
const found=spawnSync("git",["show",base+":"+file]);
if(found.status!==0){console.error("git show pinned base failed: "+found.status);process.exit(found.status??2);}
const source=found.stdout.toString("utf8");
const before="bun run test:metrics    # refresh per-test durations into test-metrics.json";
const after="bun run test:metrics    # single suite; fresh raw JUnit report outside the repository (override: NGRACE_TEST_REPORT_PATH)";
if(source.split(before).length-1!==1){console.error("expected exactly one pinned old metrics command line");process.exitCode=2;}
else if(!after.includes("fresh raw JUnit")||!after.includes("outside the repository")||!after.includes("NGRACE_TEST_REPORT_PATH")){console.error("replacement omits required report facts");process.exitCode=2;}
else {const expected=Buffer.from(source.replace(before,after),"utf8"), actual=readFileSync(file); if(Buffer.compare(actual,expected)!==0){console.error("README differs from base with only the metrics line replaced");process.exitCode=1;}else console.log("README exact-byte check OK");}
BUN
